import {HOME_STOPS} from './home-navigation.js?v=52.0.0';
export function collectionStudioHTML(s,{E,esc,picture,pose='stand'}){
 const tomorrow=s.outfitPlans.find(v=>v.day===s.day),today=s.outfitPlans.find(v=>v.forDay===s.day);
 return `<section class="home-studio-panel"><div class="home-studio-header"><div><small>YOUR ROOM · YOUR KEPT FINDS</small><h3>A little more like home.</h3></div><div class="room-finishes" role="group" aria-label="Room finish">${E.ROOM_STYLES.map(v=>`<button data-action="room-style" data-id="${v.id}" aria-pressed="${s.roomStyle===v.id}"><i style="background:${v.accent}"></i>${esc(v.name)}</button>`).join('')}</div></div><canvas id="outfit-preview" class="home-preview" width="900" height="600" tabindex="0" aria-describedby="home-walk-help room-walk-status" aria-keyshortcuts="ArrowUp ArrowDown ArrowLeft ArrowRight W A S D E Escape" aria-label="Your collection room. Focus to walk with arrows or WASD; E uses nearby furniture. Tap open floor to walk, or a fixture to use it."></canvas><div class="studio-controls home-camera-controls" role="group" aria-label="Collection room camera"><button class="active" aria-pressed="true" data-action="studio-camera" data-id="room">Whole room</button><button aria-pressed="false" data-action="studio-camera" data-id="body">My outfit</button><button aria-pressed="false" data-action="studio-camera" data-id="face">Closer look</button><button class="${pose==='stand'?'active':''}" aria-pressed="${pose==='stand'}" data-action="studio-pose" data-id="stand">Stand</button><button class="${pose==='sit'?'active':''}" aria-pressed="${pose==='sit'}" data-action="studio-pose" data-id="sit">Take a seat</button><button class="${pose==='walk'?'active':''}" aria-pressed="${pose==='walk'}" data-action="studio-pose" data-id="walk">Walk in place</button></div><div class="home-navigation"><p id="home-walk-help">Tap open floor to walk. Focus the room and use arrows or WASD; E uses nearby furniture. Escape stops walking. On touch, tap a direction to step or hold to walk.</p><div class="home-control-row"><div id="home-walk-pad" class="home-walk-pad" role="group" aria-label="Room walking controls"><button data-dir="up" aria-label="Walk up">↑</button><button data-dir="left" aria-label="Walk left">←</button><button data-action="room-stop" aria-label="Stop walking">Stop</button><button data-dir="right" aria-label="Walk right">→</button><button data-dir="down" aria-label="Walk down">↓</button></div><div><button id="room-interact" class="button secondary" data-action="room-nearby" disabled>Walk near furniture to use it</button><small id="room-walk-status" role="status">Choose a place to walk, or use a room shortcut below.</small></div></div><div class="home-walk-controls" role="group" aria-label="Walk around your collection room"><span>Walk over to…</span>${Object.entries(HOME_STOPS).map(([id,v])=>`<button data-action="room-walk" data-id="${id}">${esc(v.label.replace(/^(At |Beside |Back on )/,''))}</button>`).join('')}</div><div class="home-room-shortcuts" role="group" aria-label="Room shortcuts · no walking required">${[['shelf','Arrange my shelf'],['wardrobe','Wardrobe & looks'],['memories','Memory desk'],['window','By the window'],['door','Back to the mall']].map(([id,label])=>`<button data-action="room-use" data-id="${id}">${label}</button>`).join('')}</div></div><div class="tomorrow-plan"><div><small>TOMORROW’S SMALL PLAN</small><h4>${tomorrow?'Day '+tomorrow.forDay+' · already considered':'Two kept pieces. One less morning decision.'}</h4><p>${tomorrow?'Your prepared outfit stays here through sleep and reload.':'Equip at least two opened purchases in different slots, in your usual size. Preparing them takes 5 game minutes; it does not buy or open anything.'}</p>${tomorrow?`<div class="planned-pieces">${tomorrow.items.map(v=>`<span class="mini-art" title="${esc(E.byId(v.productId).name)}">${picture(E.byId(v.productId))}</span>`).join('')}</div>`:''}</div><div><button class="button orange" data-action="prepare-outfit" ${tomorrow?'disabled':''}>${tomorrow?'Prepared for tomorrow ✓':'Prepare my current outfit · 5 min'}</button>${today?'<button class="button secondary" data-action="apply-prepared">Put on today’s prepared look</button>':''}<button class="text-button" data-action="view" data-id="wardrobe">Wardrobe & named looks ↗</button></div></div></section>`;
}
export function guestbookHTML(s,{E,esc},selection={}){
 const done=s.guestbook.find(v=>v.day===s.day);
 return `<div class="modal-body guestbook-desk"><p>A mood and one detail worth remembering. This original Mallside guestbook stays in this browser. Signing takes <strong>5 game minutes</strong> and earns <strong>10 XP</strong>, once each day across all malls.</p>${done?`<div class="guestbook-page"><small>DAY ${done.day} · ${esc(E.mallById(done.mallId).name)}</small><h3>${esc(E.GUESTBOOK_MOODS.find(v=>v.id===done.mood).name)}</h3><p>${esc(E.GUESTBOOK_HIGHLIGHTS.find(v=>v.id===done.highlight).name)}</p><span>A small afternoon, remembered.</span></div>`:`<h3>Today felt…</h3><div class="guestbook-choices" role="group" aria-label="Guestbook mood">${E.GUESTBOOK_MOODS.map(v=>`<button data-action="guestbook-mood" data-id="${v.id}" aria-pressed="${selection.mood===v.id}">${esc(v.name)}</button>`).join('')}</div><h3>I’ll remember…</h3><div class="guestbook-choices" role="group" aria-label="Guestbook highlight">${E.GUESTBOOK_HIGHLIGHTS.map(v=>`<button data-action="guestbook-highlight" data-id="${v.id}" aria-pressed="${selection.highlight===v.id}">${esc(v.name)}</button>`).join('')}</div><button class="button orange wide" data-action="guestbook-sign" ${selection.mood&&selection.highlight?'':'disabled'}>Leave this little memory · free · 5 min</button>`}<button class="text-button" data-action="guest-services">Back to guest services</button></div>`;
}
export function guestbookMemories(s,{E,esc}){return s.guestbook.length?`<details class="guestbook-memories"><summary>Pages from ordinary afternoons · ${s.guestbook.length}</summary><div>${s.guestbook.slice(-12).reverse().map(v=>`<article><small>DAY ${v.day} · ${esc(E.mallById(v.mallId).name)}</small><strong>${esc(E.GUESTBOOK_MOODS.find(m=>m.id===v.mood).name)}</strong><p>${esc(E.GUESTBOOK_HIGHLIGHTS.find(h=>h.id===v.highlight).name)}</p></article>`).join('')}</div></details>`:'';}
